ok('4 fallos: solo «incorrectos»', !r.ok && /incorrectos$/.test(r.error), err(r));
r = await login('99990001', '0000', IP); ok('5.º fallo → «Espera 10 minutos»', !r.ok && /10 minutos/.test(r.error), err(r));
